// === ESTRUCTURA DEL PATRÓN FLYWEIGHT ===

// 1. Flyweight (interfaz)
interface CharacterFlyweight {
  render(x: number, y: number): void;
}

// 2. Flyweight Concreto (estado intrínseco compartido)
class ConcreteCharacter implements CharacterFlyweight {
  constructor(
    private char: string,
    private font: string,
    private size: number,
    private color: string
  ) {}

  render(x: number, y: number) {
    console.log(`Renderizar '${this.char}' en (${x},${y}) con ${this.font} ${this.size}px ${this.color}`);
  }
}

// 3. Fábrica de Flyweights (pool de objetos compartidos)
class CharacterFactory {
  private pool = new Map<string, CharacterFlyweight>();

  getCharacter(char: string, font: string, size: number, color: string): CharacterFlyweight {
    const key = `${char}-${font}-${size}-${color}`;

    if (!this.pool.has(key)) {
      this.pool.set(key, new ConcreteCharacter(char, font, size, color));
      console.log(`Nuevo Flyweight creado: '${char}'`);
    } else {
      console.log(`Flyweight reutilizado: '${char}'`);
    }

    return this.pool.get(key)!;
  }

  getPoolSize(): number {
    return this.pool.size;
  }
}

// 4. Cliente (estado extrínseco individual)
class Document {
  private characters: Array<{ flyweight: CharacterFlyweight; x: number; y: number }> = [];
  private factory = new CharacterFactory();

  addCharacter(char: string, x: number, y: number, font: string, size: number, color: string) {
    const flyweight = this.factory.getCharacter(char, font, size, color);
    this.characters.push({ flyweight, x, y });
  }

  render() {
    this.characters.forEach(({ flyweight, x, y }) => {
      flyweight.render(x, y);
    });
  }
}

// Uso:
const doc = new Document();
doc.addCharacter('H', 0, 0, 'Arial', 12, '#000');
doc.addCharacter('o', 10, 0, 'Arial', 12, '#000');
doc.addCharacter('l', 20, 0, 'Arial', 12, '#000');
doc.addCharacter('a', 30, 0, 'Arial', 12, '#000');
// Solo 3 Flyweights se crearon (H, o, l, a = 4 únicos)
// Pero se renderizaron 4 caracteres en posiciones diferentes

