// Cada carácter almacena TODAS sus propiedades — masivo consumo de memoria
class Character {
  constructor(
    public char: string,
    public x: number,
    public y: number,
    public font: string,
    public size: number,
    public color: string
  ) {}
}

// 100,000 caracteres = 100,000 objetos con 6 propiedades cada uno
const doc: Character[] = [];
for (let i = 0; i < 100000; i++) {
  doc.push(new Character('A', i * 10, 0, 'Arial', 12, '#000'));
}
// Memoria: 100,000 × 6 propiedades = 600,000 datos

