// Flyweight — estado intrínseco compartido, extrínseco individual
const factory = new CharacterFactory();
const doc: Array<{ flyweight: CharacterFlyweight; x: number; y: number }> = [];

// 100,000 caracteres 'A' = SOLO 1 Flyweight reutilizado
for (let i = 0; i < 100000; i++) {
  const fw = factory.getCharacter('A', 'Arial', 12, '#000');
  doc.push({ flyweight: fw, x: i * 10, y: 0 });
}
// Memoria: 1 Flyweight (intrínseco) + 100,000 referencias (extrínseco)
console.log(factory.getPoolSize()); // 1 — solo un Flyweight

